const leads = $('Fetch Active Leads').all() || [];
const scoredLeads = [];

for (const lead of leads) {
  const l = lead.json;
  let score = l.lead_score || 0;
  const daysSinceUpdate = Math.floor((Date.now() - new Date(l.updated_at || l.created_at).getTime()) / (24*60*60*1000));

  // Decay: lose points for inactivity
  if (daysSinceUpdate > 7) score = Math.max(0, score - 5);
  if (daysSinceUpdate > 14) score = Math.max(0, score - 10);
  if (daysSinceUpdate > 30) score = Math.max(0, score - 20);

  // Recalculate qualification
  let qualification = 'cold';
  if (score >= 60) qualification = 'hot';
  else if (score >= 35) qualification = 'warm';

  scoredLeads.push({
    id: l.id,
    lead_score: score,
    qualification,
    days_inactive: daysSinceUpdate,
    needs_attention: daysSinceUpdate > 7 && qualification !== 'cold'
  });
}

return {
  json: {
    total_scored: scoredLeads.length,
    hot: scoredLeads.filter(l => l.qualification === 'hot').length,
    warm: scoredLeads.filter(l => l.qualification === 'warm').length,
    cold: scoredLeads.filter(l => l.qualification === 'cold').length,
    needs_attention: scoredLeads.filter(l => l.needs_attention).length,
    leads: scoredLeads
  }
};
